import React from 'react';
import { Icons } from './ui/Icons';
import '../styles/global.css';

export function Header({ scrolled, page, setPage, setModal, setCartOpen, cartCount }) {
    return (
        <header className={`hdr${scrolled ? " compact" : ""}`}>
            <div className="brand">
                <div className="brand-name">Ёмаё</div>
                <div className="brand-sub">Ресторан</div>
            </div>
            <nav className="nav">
                {["Главная", "Меню", "Резервирование", "Контакты"].map(n => (
                    <button
                        key={n}
                        className={`nav-btn${(n === "Главная" && page === "home") || (n === "Меню" && page === "menu") ? " on" : ""}`}
                        onClick={() => {
                            if (n === "Резервирование") {
                                setModal("reserve");
                                return;
                            }
                            if (n === "Меню") {
                                setPage("menu");
                                return;
                            }
                            setPage("home");
                        }}
                    >
                        {n}
                    </button>
                ))}
            </nav>
            <div className="hdr-right">
                <button className="ico-btn" onClick={() => setModal("login")} title="Войти">
                    <Icons.User />
                </button>
                <button className="ico-btn" onClick={() => setCartOpen(true)} title="Корзина">
                    <Icons.Cart />
                    {cartCount > 0 && <span className="bdg">{cartCount}</span>}
                </button>
            </div>
        </header>
    );
}
